SELECT FROM job_application WHERE user_id = #{userId}
AND archived = 0
ORDER BY CASE stage WHEN 'OFFER' THEN 0 WHEN 'HR' THEN 1 WHEN 'INTERVIEWING' THEN 2 WHEN 'WRITTEN_TEST' THEN 3 WHEN 'APPLIED' THEN 4 WHEN 'WATCHING' THEN 5 ELSE 6 END, updated_at DESC, id DESC

