UPDATE job_application
SET stage = #{stage},
    stage_changed_at = #{stageChangedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND stage = #{expectedStage}

UPDATE job_application
SET archived = #{archived},
    updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId} AND archived <> #{archived}

